[{"type":"text","text":"import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const e2eDir = path.resolve(__dirname, '..')
const projectRoot = path.resolve(__dirname, '../../..')

let envLoaded = false

function loadEnvFile(filePath, { override = false } = {}) {
  if (!fs.existsSync(filePath)) return
  const content = fs.readFileSync(filePath, 'utf8').replace(/^\uFEFF/, '')
  for (const line of content.split(/\r?\n/)) {
    const trimmed = line.trim()
    if (!trimmed || trimmed.startsWith('#')) continue
    const idx = trimmed.indexOf('=')
    if (idx === -1) continue
    const key = trimmed.slice(0, idx).trim()
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) continue
    let val = trimmed.slice(idx + 1).trim()
    if (
      (val.startsWith('"') && val.endsWith('"'))
      || (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1)
    }
    if (override || !(key in process.env) || process.env[key] === '') {
      process.env[key] = val
    }
  }
}

export function loadE2eEnv() {
  if (envLoaded) return
  const explicitBaseURL = process.env.E2E_BASE_URL
  loadEnvFile(path.join(e2eDir, '.env.e2e.example'))
  loadEnvFile(path.join(e2eDir, '.env.e2e'), { override: true })
  loadEnvFile(path.join(projectRoot, 'env', '.env.e2e'), { override: true })
  loadEnvFile(path.join(projectRoot, 'env', '.env.local'))
  // 命令行指定的目标地址优先，避免配置文件覆盖后误测其它工作区服务。
  if (explicitBaseURL) process.env.E2E_BASE_URL = explicitBaseURL
  envLoaded = true
}

export function getCompanyUsername() {
  loadE2eEnv()
  return (
    process.env.PLAYWRIGHT_AGENCY_COMPANY_USERNAME
    || process.env.PLAYWRIGHT_COMPANY_USERNAME
    || (process.env.PLAYWRIGHT_LOGIN_TYPE === 'company' ? process.env.PLAYWRIGHT_LOGIN_USER : '')
    || process.env.E2E_LOGIN_USER
    || ''
  )
}

export function getCompanyPassword() {
  loadE2eEnv()
  return (
    process.env.PLAYWRIGHT_AGENCY_COMPANY_PASSWORD
"}]

